import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.LongSupplier;

public class Solution {
    record Backend(String id, int peso) {}

    record Requisicao(String host, String caminho, Map<String, String> cabecalhos) {
        static Requisicao de(String host, String caminho) {
            return new Requisicao(host, caminho, Map.of());
        }

        Requisicao com(String cabecalho, String valor) {
            Map<String, String> copia = new HashMap<>(cabecalhos);
            copia.put(cabecalho.toLowerCase(Locale.ROOT), valor);
            return new Requisicao(host, caminho, copia);
        }

        String cabecalho(String nome) {
            return cabecalhos.get(nome.toLowerCase(Locale.ROOT));
        }
    }

    record Resposta(int status, String backend) {}

    static final class Balanceador {
        private record Regra(String host, String prefixo, List<Backend> backends) {}

        private final long reentradaMs;
        private final LongSupplier relogio;
        private final List<Regra> regras = new ArrayList<>();
        private final Map<String, Long> falhas = new HashMap<>();
        private final Map<String, Integer> andamento = new HashMap<>();

        Balanceador(long reentradaMs, LongSupplier relogio) {
            if (reentradaMs <= 0) throw new IllegalArgumentException("reentradaMs precisa ser > 0");
            if (relogio == null) throw new IllegalArgumentException("relógio nulo");
            this.reentradaMs = reentradaMs;
            this.relogio = relogio;
        }

        synchronized void adicionarRota(String host, String prefixo, List<Backend> backends) {
            if (host == null || prefixo == null || backends == null) throw new IllegalArgumentException("argumento nulo");
            if (!prefixo.startsWith("/")) throw new IllegalArgumentException("prefixo precisa começar com /");
            if (backends.isEmpty()) throw new IllegalArgumentException("sem backends");
            Set<String> ids = new HashSet<>();
            for (Backend b : backends) {
                if (b == null || b.id() == null || b.peso() < 1) throw new IllegalArgumentException("backend inválido");
                if (!ids.add(b.id())) throw new IllegalArgumentException("id repetido: " + b.id());
            }
            Regra nova = new Regra(host.toLowerCase(Locale.ROOT), semBarraFinal(prefixo), List.copyOf(backends));
            regras.removeIf(r -> r.host().equals(nova.host()) && r.prefixo().equals(nova.prefixo()));
            regras.add(nova);
        }

        synchronized Resposta rotear(Requisicao req) {
            String host = normalizarHost(req.host());
            String caminho = normalizarCaminho(req.caminho());
            Regra melhor = null;
            boolean melhorExata = false;
            for (Regra r : regras) {
                boolean exata = r.host().equals(host);
                if (!exata && !r.host().equals("*")) continue;
                if (!casa(r.prefixo(), caminho)) continue;
                if (melhor == null
                        || (exata && !melhorExata)
                        || (exata == melhorExata && r.prefixo().length() > melhor.prefixo().length())) {
                    melhor = r;
                    melhorExata = exata;
                }
            }
            if (melhor == null) return new Resposta(404, null);

            List<Backend> vivos = new ArrayList<>();
            for (Backend b : melhor.backends()) if (saudavel(b.id())) vivos.add(b);
            if (vivos.isEmpty()) return new Resposta(503, null);

            Backend escolhido;
            String chave = req.cabecalho("X-Afinidade");
            if (chave != null) {
                escolhido = vivos.get(Math.floorMod(chave.hashCode(), vivos.size()));
            } else {
                escolhido = vivos.get(0);
                for (Backend b : vivos.subList(1, vivos.size())) {
                    // b é estritamente melhor se andamento(b)/peso(b) < andamento(escolhido)/peso(escolhido)
                    if ((long) emAndamento(b.id()) * escolhido.peso() < (long) emAndamento(escolhido.id()) * b.peso()) escolhido = b;
                }
            }
            andamento.merge(escolhido.id(), 1, Integer::sum);
            return new Resposta(200, escolhido.id());
        }

        synchronized void concluir(String idBackend) {
            int atual = andamento.getOrDefault(idBackend, 0);
            if (atual <= 0) throw new IllegalStateException("nenhuma requisição em andamento em " + idBackend);
            andamento.put(idBackend, atual - 1);
        }

        synchronized void marcarFalha(String idBackend) {
            falhas.put(idBackend, relogio.getAsLong());
        }

        synchronized void marcarSaudavel(String idBackend) {
            falhas.remove(idBackend);
        }

        synchronized boolean saudavel(String idBackend) {
            Long desde = falhas.get(idBackend);
            return desde == null || relogio.getAsLong() - desde >= reentradaMs;
        }

        synchronized int emAndamento(String idBackend) {
            return andamento.getOrDefault(idBackend, 0);
        }

        // ---------- normalização ----------

        private static String semBarraFinal(String prefixo) {
            return prefixo.length() > 1 && prefixo.endsWith("/") ? prefixo.substring(0, prefixo.length() - 1) : prefixo;
        }

        private static String normalizarHost(String host) {
            String h = host == null ? "" : host.toLowerCase(Locale.ROOT);
            int dois = h.indexOf(':');
            return dois >= 0 ? h.substring(0, dois) : h;
        }

        private static String normalizarCaminho(String caminho) {
            String c = caminho == null ? "" : caminho;
            int q = c.indexOf('?');
            if (q >= 0) c = c.substring(0, q);
            int f = c.indexOf('#');
            if (f >= 0) c = c.substring(0, f);
            return semBarraFinal(c);
        }

        private static boolean casa(String prefixo, String caminho) {
            return prefixo.equals("/") || caminho.equals(prefixo) || caminho.startsWith(prefixo + "/");
        }
    }
}

