import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;

class SolutionTest {
    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio em(long t) { agora = t; return this; }
    }

    static Solution.Backend b(String id, int peso) { return new Solution.Backend(id, peso); }
    static Solution.Requisicao req(String host, String caminho) { return Solution.Requisicao.de(host, caminho); }
    static Solution.Balanceador lb(Relogio t) { return new Solution.Balanceador(1000, t); }
    static String quem(Solution.Balanceador l, Solution.Requisicao r) {
        Solution.Resposta resp = l.rotear(r);
        assertEquals(200, resp.status(), "esperava 200 para " + r);
        return resp.backend();
    }

    // ---------- roteamento ----------

    @Test void semRotaDevolve404() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("loja.com", "/api", List.of(b("a", 1)));
        assertEquals(new Solution.Resposta(404, null), l.rotear(req("loja.com", "/outra")));
        assertEquals(new Solution.Resposta(404, null), l.rotear(req("outro.com", "/api")));
    }

    @Test void prefixoMaisLongoVence() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("web", 1)));
        l.adicionarRota("*", "/api", List.of(b("api", 1)));
        l.adicionarRota("*", "/api/admin", List.of(b("admin", 1)));
        assertEquals("web", quem(l, req("x.com", "/index.html")));
        assertEquals("api", quem(l, req("x.com", "/api/pedidos")));
        assertEquals("admin", quem(l, req("x.com", "/api/admin/usuarios")));
        assertEquals("api", quem(l, req("x.com", "/api")));
        assertEquals("admin", quem(l, req("x.com", "/api/admin")));
    }

    @Test void prefixoCasaSoNoLimiteDeSegmento() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("web", 1)));
        l.adicionarRota("*", "/api", List.of(b("api", 1)));
        assertEquals("web", quem(l, req("x.com", "/apiv2")));
        assertEquals("web", quem(l, req("x.com", "/apis/lista")));
    }

    @Test void barraFinalNoPrefixoEquivaleASem() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/api/", List.of(b("api", 1)));
        assertEquals("api", quem(l, req("x.com", "/api")));
        assertEquals("api", quem(l, req("x.com", "/api/x")));
    }

    @Test void hostExatoVenceCuringaMesmoComPrefixoMenor() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/api/pedidos", List.of(b("geral", 1)));
        l.adicionarRota("loja.com", "/api", List.of(b("loja", 1)));
        assertEquals("loja", quem(l, req("loja.com", "/api/pedidos")));
        assertEquals("geral", quem(l, req("outro.com", "/api/pedidos")));
    }

    @Test void hostIgnoraMaiusculasEPorta() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("Loja.Com", "/", List.of(b("loja", 1)));
        assertEquals("loja", quem(l, req("LOJA.com:8443", "/")));
        assertEquals("loja", quem(l, req("loja.com", "/")));
    }

    @Test void queryFragmentoECaminhoVazioSaoTratados() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("web", 1)));
        l.adicionarRota("*", "/api", List.of(b("api", 1)));
        assertEquals("api", quem(l, req("x.com", "/api?x=1")));
        assertEquals("api", quem(l, req("x.com", "/api/lista?x=/web")));
        assertEquals("api", quem(l, req("x.com", "/api#topo")));
        assertEquals("web", quem(l, req("x.com", "")));
    }

    @Test void rotaComMesmoHostEPrefixoSubstitui() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/api", List.of(b("velho", 1)));
        l.adicionarRota("*", "/api", List.of(b("novo", 1)));
        assertEquals("novo", quem(l, req("x.com", "/api")));
    }

    // ---------- seleção ----------

    @Test void menosRequisicoesEmAndamentoComEmpatePeloPrimeiro() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1), b("c", 1)));
        List<String> seq = new ArrayList<>();
        for (int i = 0; i < 6; i++) seq.add(quem(l, req("x.com", "/")));
        assertEquals(List.of("a", "b", "c", "a", "b", "c"), seq);
        assertEquals(2, l.emAndamento("a"));
    }

    @Test void concluirDevolveCapacidade() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1)));
        assertEquals("a", quem(l, req("x.com", "/")));
        assertEquals("b", quem(l, req("x.com", "/")));
        l.concluir("a");
        assertEquals(0, l.emAndamento("a"));
        assertEquals("a", quem(l, req("x.com", "/")), "a ficou com menos em andamento");
        l.concluir("b");
        l.concluir("a");
        assertEquals("a", quem(l, req("x.com", "/")), "empate: o primeiro");
    }

    @Test void pesoDoBackendDefineAProporcao() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 2), b("b", 1)));
        List<String> seq = new ArrayList<>();
        for (int i = 0; i < 6; i++) seq.add(quem(l, req("x.com", "/")));
        assertEquals(List.of("a", "b", "a", "a", "b", "a"), seq);
        assertEquals(4, l.emAndamento("a"));
        assertEquals(2, l.emAndamento("b"));
    }

    @Test void contadorEPorIdECompartilhadoEntreRotas() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/x", List.of(b("a", 1), b("b", 1)));
        l.adicionarRota("*", "/y", List.of(b("b", 1), b("c", 1)));
        assertEquals("a", quem(l, req("h.com", "/x")));
        assertEquals("b", quem(l, req("h.com", "/x")));
        assertEquals("c", quem(l, req("h.com", "/y")), "b já tem 1 em andamento por causa de /x");
        assertEquals(1, l.emAndamento("b"));
    }

    @Test void concluirSemAndamentoLanca() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1)));
        assertThrows(IllegalStateException.class, () -> l.concluir("a"));
        quem(l, req("x.com", "/"));
        l.concluir("a");
        assertThrows(IllegalStateException.class, () -> l.concluir("a"));
    }

    // ---------- afinidade ----------

    @Test void afinidadePorCabecalhoEEstavel() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1), b("c", 1)));
        for (String chave : List.of("cliente-1", "cliente-2", "cliente-3", "cliente-42")) {
            String esperado = List.of("a", "b", "c").get(Math.floorMod(chave.hashCode(), 3));
            for (int i = 0; i < 3; i++) {
                assertEquals(esperado, quem(l, req("x.com", "/").com("X-Afinidade", chave)), chave);
            }
        }
    }

    @Test void afinidadeIgnoraACarga() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1)));
        String chave = "k";
        String alvo = List.of("a", "b").get(Math.floorMod(chave.hashCode(), 2));
        for (int i = 0; i < 5; i++) assertEquals(alvo, quem(l, req("x.com", "/").com("x-afinidade", chave)));
        assertEquals(5, l.emAndamento(alvo));
    }

    @Test void afinidadeUsaSoOsSaudaveis() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1), b("c", 1)));
        l.marcarFalha("a");
        for (String chave : List.of("u1", "u2", "u3", "u4", "u5")) {
            String esperado = List.of("b", "c").get(Math.floorMod(chave.hashCode(), 2));
            assertEquals(esperado, quem(l, req("x.com", "/").com("X-Afinidade", chave)), chave);
        }
    }

    // ---------- saúde ----------

    @Test void backendComFalhaSaiDaRotacao() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1)));
        l.marcarFalha("a");
        assertFalse(l.saudavel("a"));
        assertTrue(l.saudavel("b"));
        for (int i = 0; i < 4; i++) assertEquals("b", quem(l, req("x.com", "/")));
    }

    @Test void voltaSozinhoAposAReentradaNaFronteira() {
        Relogio t = new Relogio();
        Solution.Balanceador l = lb(t);
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1)));
        t.em(100);
        l.marcarFalha("a");
        t.em(1099);
        assertFalse(l.saudavel("a"), "999 ms: ainda fora");
        assertEquals("b", quem(l, req("x.com", "/")));
        t.em(1100);
        assertTrue(l.saudavel("a"), "1000 ms: voltou");
        assertEquals("a", quem(l, req("x.com", "/")), "a tem 0 em andamento contra 1 de b");
    }

    @Test void novaFalhaReiniciaAContagem() {
        Relogio t = new Relogio();
        Solution.Balanceador l = lb(t);
        l.adicionarRota("*", "/", List.of(b("a", 1)));
        l.marcarFalha("a");
        t.em(900);
        l.marcarFalha("a");
        t.em(1500);
        assertFalse(l.saudavel("a"), "600 ms desde a segunda falha");
        t.em(1900);
        assertTrue(l.saudavel("a"));
    }

    @Test void marcarSaudavelVoltaNaHora() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1)));
        l.marcarFalha("a");
        l.marcarSaudavel("a");
        assertTrue(l.saudavel("a"));
        assertEquals("a", quem(l, req("x.com", "/")));
    }

    @Test void semBackendSaudavelDevolve503NaoDevolve404() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/api", List.of(b("a", 1), b("b", 1)));
        l.marcarFalha("a");
        l.marcarFalha("b");
        assertEquals(new Solution.Resposta(503, null), l.rotear(req("x.com", "/api")));
        assertEquals(new Solution.Resposta(404, null), l.rotear(req("x.com", "/outra")));
        assertEquals(0, l.emAndamento("a"));
    }

    @Test void falhaEPorIdEValeEmTodasAsRotas() {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/x", List.of(b("a", 1), b("c", 1)));
        l.adicionarRota("*", "/y", List.of(b("a", 1)));
        l.marcarFalha("a");
        assertEquals("c", quem(l, req("h.com", "/x")));
        assertEquals(503, l.rotear(req("h.com", "/y")).status());
    }

    // ---------- argumentos ----------

    @Test void argumentosInvalidos() {
        Relogio t = new Relogio();
        assertThrows(IllegalArgumentException.class, () -> new Solution.Balanceador(0, t));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Balanceador(1000, null));
        Solution.Balanceador l = lb(t);
        assertThrows(IllegalArgumentException.class, () -> l.adicionarRota("*", "api", List.of(b("a", 1))));
        assertThrows(IllegalArgumentException.class, () -> l.adicionarRota("*", "/api", List.of()));
        assertThrows(IllegalArgumentException.class, () -> l.adicionarRota("*", "/api", List.of(b("a", 0))));
        assertThrows(IllegalArgumentException.class, () -> l.adicionarRota("*", "/api", List.of(b("a", 1), b("a", 2))));
        assertThrows(IllegalArgumentException.class, () -> l.adicionarRota(null, "/api", List.of(b("a", 1))));
    }

    // ---------- concorrência ----------

    @Test void contagemNaoSePerdeComVariasThreads() throws Exception {
        Solution.Balanceador l = lb(new Relogio());
        l.adicionarRota("*", "/", List.of(b("a", 1), b("b", 1), b("c", 1)));
        final int threads = 8, voltas = 600;
        CountDownLatch largada = new CountDownLatch(1);
        CountDownLatch fim = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                try {
                    largada.await();
                    for (int v = 0; v < voltas; v++) l.rotear(req("x.com", "/"));
                } catch (InterruptedException ignorada) {
                } finally {
                    fim.countDown();
                }
            }).start();
        }
        largada.countDown();
        assertTrue(fim.await(20, TimeUnit.SECONDS));
        int total = l.emAndamento("a") + l.emAndamento("b") + l.emAndamento("c");
        assertEquals(threads * voltas, total);
        assertEquals(total / 3, l.emAndamento("a"), "a carga fica uniforme");
    }
}
